  const effectiveConfig = () => {
    const raw = current() ?? {};
    const providers = providerSettings(raw);
    const configured = providers[PROVIDER] ?? providers[LEGACY_PROVIDER];
    return {
      ...raw,
      providers: {
        ...providers,
        [PROVIDER]: configured ?? { apiKeyEnv: API_KEY_ENV },
